// TypeScript Version: 4.1

/**
* Interface describing constructor options.
*/
interface Options {
	/**
	* Multiplication factor for the band width of a scale.
	*/
	band?: number;

	/**
	* Color value specifying per-channel references.
	*/
	color?: Record<string, unknown>;

	/**
	* Scale exponent modifier.
	*/
	exponent?: number | Value;

	/**
	* Data field name or descriptor.
	*/
	field?: string | Record<string, unknown>;

	/**
	* Scale multiplier modifier.
	*/
	mult?: number | Value;

	/**
	* Scale additive offset.
	*/
	offset?: number | Value;

	/**
	* Boolean indicating whether to round a value after scale transformations.
	*/
	round?: boolean;

	/**
	* Name of scale transform to apply or a field descriptor.
	*/
	scale?: string | Record<string, unknown>;

	/**
	* Signal name or expression.
	*/
	signal?: string;

	/**
	* Constant value.
	*/
	value?: any;
}

/**
* Interface describing a JSON-serialized value instance.
*/
interface JSON {
	/**
	* Multiplication factor for the band width of a scale.
	*/
	band?: number;

	/**
	* Color value specifying per-channel references.
	*/
	color?: Record<string, unknown>;

	/**
	* Scale exponent modifier.
	*/
	exponent?: number | Value;

	/**
	* Data field name or descriptor.
	*/
	field?: string | Record<string, unknown>;

	/**
	* Scale multiplier modifier.
	*/
	mult?: number | Value;

	/**
	* Scale additive offset.
	*/
	offset?: number | Value;

	/**
	* Boolean indicating whether to round a value after scale transformations.
	*/
	round?: boolean;

	/**
	* Name of a scale transform to apply or a field descriptor.
	*/
	scale?: string | Record<string, unknown>;

	/**
	* Signal name or expression.
	*/
	signal?: string;

	/**
	* Constant value.
	*/
	value?: any;
}

/**
* Interface describing a value instance.
*/
interface Value {
	/**
	* Multiplication factor for the band width of a scale.
	*
	* @example
	* var value = new Value();
	*
	* value.band = 0.5;
	*
	* var v = value.band;
	* // returns 0.5
	*/
	band?: number;

	/**
	* Color value specifying per-channel references.
	*
	* @example
	* var value = new Value();
	*
	* value.color = {
	*     'r': {
	*         'value': 255
	*     },
	*     'g': {
	*         'value': 0
	*     },
	*     'b': {
	*         'value': 0
	*     }
	* };
	*
	* var v = value.color;
	* // returns { 'r': { 'value': 255 }, 'g': { 'value': 0 }, 'b': { 'value': 0 } }
	*/
	color?: Record<string, unknown>;

	/**
	* Scale exponent modifier.
	*
	* @example
	* var value = new Value();
	*
	* value.exponent = 2;
	*
	* var v = value.exponent;
	* // returns 2
	*/
	exponent?: number | Value;

	/**
	* Data field name or descriptor.
	*
	* @example
	* var value = new Value();
	*
	* value.field = 'price';
	*
	* var v = value.field;
	* // returns 'price'
	*/
	field?: string | Record<string, unknown>;

	/**
	* Scale multiplier modifier.
	*
	* @example
	* var value = new Value();
	*
	* value.mult = 2;
	*
	* var v = value.mult;
	* // returns 2
	*/
	mult?: number | Value;

	/**
	* Scale additive offset.
	*
	* @example
	* var value = new Value();
	*
	* value.offset = 5;
	*
	* var v = value.offset;
	* // returns 5
	*/
	offset?: number | Value;

	/**
	* Boolean indicating whether to round a value after scale transformations.
	*
	* @example
	* var value = new Value();
	*
	* value.round = true;
	*
	* var v = value.round;
	* // returns true
	*/
	round?: boolean;

	/**
	* Name of a scale transform to apply or a field descriptor.
	*
	* @example
	* var value = new Value();
	*
	* value.scale = 'xScale';
	*
	* var v = value.scale;
	* // returns 'xScale'
	*/
	scale?: string | Record<string, unknown>;

	/**
	* Signal name or expression.
	*
	* @example
	* var value = new Value();
	*
	* value.signal = 'width';
	*
	* var v = value.signal;
	* // returns 'width'
	*/
	signal?: string;

	/**
	* Constant value.
	*
	* @example
	* var value = new Value();
	*
	* value.value = 5;
	*
	* var v = value.value;
	* // returns 5
	*/
	value?: any;

	/**
	* List of enumerable properties.
	*
	* @example
	* var value = new Value();
	*
	* var v = value.properties;
	* // returns [ 'band', 'color', 'exponent', 'field', 'mult', 'offset', 'round', 'scale', 'signal', 'value' ]
	*/
	readonly properties: Array<string>;

	/**
	* Serializes a value instance to a JSON object.
	*
	* ## Notes
	*
	* -   This method is implicitly invoked by `JSON.stringify`.
	*
	* @returns JSON object
	*
	* @example
	* var value = new Value({
	*     'field': 'price'
	* });
	*
	* var v = value.toJSON();
	* // returns { 'field': 'price' }
	*/
	toJSON(): JSON;
}

/**
* Interface defining a value constructor which is both "newable" and "callable".
*/
interface Constructor {
	/**
	* Value constructor.
	*
	* @param options - constructor options
	* @param options.band - multiplication factor for the band width of a scale
	* @param options.color - color value specifying per-channel references
	* @param options.exponent - scale exponent modifier
	* @param options.field - data field name or descriptor
	* @param options.mult - scale multiplier modifier
	* @param options.offset - scale additive offset
	* @param options.round - boolean indicating whether to round a value after scale transformations
	* @param options.scale - name of scale transform to apply or a field descriptor
	* @param options.signal - signal name or expression
	* @param options.value - constant value
	* @throws options argument must be an object
	* @throws must provide valid options
	* @returns value instance
	*
	* @example
	* var value = new Value({
	*     'field': 'price'
	* });
	*
	* var v = value.field;
	* // returns 'price'
	*/
	new ( options?: Options ): Value;

	/**
	* Value constructor.
	*
	* @param options - constructor options
	* @param options.band - multiplication factor for the band width of a scale
	* @param options.color - color value specifying per-channel references
	* @param options.exponent - scale exponent modifier
	* @param options.field - data field name or descriptor
	* @param options.mult - scale multiplier modifier
	* @param options.offset - scale additive offset
	* @param options.round - boolean indicating whether to round a value after scale transformations
	* @param options.scale - name of scale transform to apply or a field descriptor
	* @param options.signal - signal name or expression
	* @param options.value - constant value
	* @throws options argument must be an object
	* @throws must provide valid options
	* @returns value instance
	*
	* @example
	* var value = Value({
	*     'field': 'price'
	* });
	*
	* var v = value.field;
	* // returns 'price'
	*/
	( options?: Options ): Value;
}

/**
* Value constructor.
*
* @param options - constructor options
* @param options.band - multiplication factor for the band width of a scale
* @param options.color - color value specifying per-channel references
* @param options.exponent - scale exponent modifier
* @param options.field - data field name or descriptor
* @param options.mult - scale multiplier modifier
* @param options.offset - scale additive offset
* @param options.round - boolean indicating whether to round a value after scale transformations
* @param options.scale - name of scale transform to apply or a field descriptor
* @param options.signal - signal name or expression
* @param options.value - constant value
* @throws options argument must be an object
* @throws must provide valid options
* @returns value instance
*
* @example
* var value = new Value();
* // returns <Value>
*
* var v = value.toJSON();
* // returns {}
*/
declare var ctor: Constructor;


// EXPORTS //

export = ctor;

// eslint-doctest-alias: Value
